// Ranged combat, phase 2: defenses against ranged attacks. Research: docs/RANGED-COMBAT-RESEARCH.md;
// rulings: DECISIONS.md (wind is left to the GM).
//
// Rules:
//   - Deflect Arrows: "Once per round when you would normally be hit with an attack from a ranged weapon,
//     you may deflect it so that you take no damage from it. You must be aware of the attack and not
//     flat-footed... Unusually massive ranged weapons ... and ranged attacks generated by natural attacks
//     or spell effects can't be deflected." Missile Shield works the same with a shield; an arrow
//     deflection shield needs a DC 20 Reflex save (+ the weapon's enhancement bonus); Cut from the Air
//     needs a melee attack roll above the ranged attack's. Mythic versions add half the tier in uses.
//     Snatch Arrows catches it instead. The defender chooses: a button on the attack card.
//   - Damage reduction against ranged weapons: Protection from Arrows (DR 10/magic, discharged after
//     absorbing 10 points per caster level, maximum 100), Arrowmaster's Bracers (DR 5/magic), the archer's
//     ranged defense (DR 5/–). The best one applies; a weapon with an enhancement bonus overcomes /magic.
//   - AC against ranged attacks (Table 8-6): prone +4 (Prone Shooter +6). Deflection against ranged
//     weapons (Bullet Shield +4, +1 per 5 caster levels, maximum +8; Arrowmaster's Bracers +1; arrow
//     catching shields +1) doesn't stack with other deflection bonuses. Rebounding shields +2 and
//     Charau-Ka Slayer +1 against thrown weapons; Breeze-Kissed +2 against nonmagical ranged attacks; Low
//     Profile +1 dodge; Armor of Arrow Attraction –15. Shown under the attack, after the roll, to the GM
//     and the target's owner only (players don't see enemy statistics); a deflection is shown to all.
//   - Firearms (Ultimate Combat): "the attack resolves against the target's touch AC when the target is
//     within the first range increment" (early firearms; advanced: within five increments), "but this
//     type of attack is not considered a touch attack for the purposes of feats and abilities such as
//     Deadly Aim". Pinpoint Targeting: "The target does not gain any armor, natural armor, or shield
//     bonuses to its Armor Class." Both shown on the AC line.
//   - Prone attackers can't use most ranged weapons: crossbows, shuriken and firearms can (Prone Slinger:
//     slings). A warning, not a block.

import { MODULE_ID, RANGED_ATTACKS } from "./const.mjs";
import { esc, onGmRequest, requestedByOwner, equippedItem, tokenDistance } from "./util.mjs";
import { rollPlan } from "./roll-effects.mjs";
import { rangeChanges } from "./ranged.mjs";
import { loading } from "./ranged-actions.mjs";

const FLAG = "rangedDefense";
const WEAPON_ATTACKS = ["rwak", "twak"]; // ranged weapon attacks (not spells, not maneuvers)
const feat = (actor, re) => (actor?.itemTypes?.feat ?? []).find((f) => f.isActive !== false && re.test(f.name)) ?? null;
const buff = (actor, re) => (actor?.itemTypes?.buff ?? []).find((b) => b.isActive && re.test(b.name)) ?? null;
const enhancement = (action) => Number(action?.item?.system?.enh ?? 0) || 0;
const isNatural = (action) => action?.item?.subType === "natural";

/* -------------------------------------------- */
/*  AC against ranged attacks                   */
/* -------------------------------------------- */

/** The defender's existing deflection bonus to AC (the highest; deflection bonuses don't stack). */
function deflectionNow(actor) {
  return Math.max(0, ...(actor?.changes ?? []).filter((c) => ["ac", "aac"].includes(c.target) && c.type === "deflection").map((c) => c.value ?? 0));
}

/** AC changes against this ranged attack: [{ value, label }]. */
export function acAgainstRanged(defender, action) {
  const out = [];
  const weapon = WEAPON_ATTACKS.includes(action?.actionType);
  const thrown = action?.actionType === "twak";
  if (defender.statuses?.has("prone")) out.push(feat(defender, /^prone shooter/i) ? { value: 6, label: "prone (Prone Shooter)" } : { value: 4, label: "prone" });
  if (weapon) {
    const deflections = [];
    const bulletShield = buff(defender, /^bullet shield/i);
    if (bulletShield) deflections.push({ value: Math.min(8, 4 + Math.floor((bulletShield.system.level ?? 0) / 5)), label: bulletShield.name });
    const bracers = equippedItem(defender, /arrowmaster'?s bracers/i);
    if (bracers) deflections.push({ value: 1, label: bracers.name });
    const catching = equippedItem(defender, /arrow catching/i);
    if (catching) deflections.push({ value: 1, label: catching.name });
    const best = deflections.reduce((a, b) => (!a || b.value > a.value ? b : a), null);
    const extra = best ? best.value - deflectionNow(defender) : 0;
    if (extra > 0) out.push({ value: extra, label: `${best.label} (deflection)` });
    const attraction = equippedItem(defender, /armor of arrow attraction/i);
    if (attraction) out.push({ value: -15, label: attraction.name });
  }
  if (thrown) {
    const rebounding = equippedItem(defender, /rebounding/i);
    if (rebounding) out.push({ value: 2, label: rebounding.name });
    if (feat(defender, /^charau-ka slayer/i)) out.push({ value: 1, label: "Charau-Ka Slayer" });
  }
  if (feat(defender, /^breeze-kissed/i) && weapon && !enhancement(action)) out.push({ value: 2, label: "Breeze-Kissed" });
  if (feat(defender, /^low profile/i)) out.push({ value: 1, label: "Low Profile (dodge)" });
  return out;
}

/* -------------------------------------------- */
/*  Deflecting                                  */
/* -------------------------------------------- */

/** How the defender can deflect this attack: { label, save?, cutFromTheAir?, catches, perRound } or null. */
export function deflectorOf(defender, action) {
  if (!WEAPON_ATTACKS.includes(action?.actionType) || isNatural(action)) return null;
  if (defender.statuses?.has("flatFooted")) return null;
  const catches = !!feat(defender, /^snatch arrows/i);
  const mythic = feat(defender, /^(deflect arrows|missile shield) \(mythic\)/i);
  const tier = defender.system.details?.mythicTier ?? 0;
  const perRound = 1 + (mythic ? Math.floor(tier / 2) : 0);
  const shield = defender.items.find((i) => i.type === "equipment" && i.system.equipped && i.system.subType === "shield");
  const deflect = feat(defender, /^deflect arrows/i) ?? (shield && feat(defender, /^missile shield/i)) ?? equippedItem(defender, /vambraces of defense/i) ?? (!defender.statuses?.has("fly") && equippedItem(defender, /wicked wings/i));
  if (deflect) return { label: deflect.name, catches, perRound };
  const arrowDeflection = defender.items.find((i) => i.type === "equipment" && i.system.equipped && /arrow deflection/i.test(i.name));
  if (arrowDeflection) return { label: arrowDeflection.name, save: 20 + enhancement(action), catches, perRound };
  const cut = feat(defender, /^cut from the air/i);
  if (cut) return { label: cut.name, cutFromTheAir: true, catches: false, perRound };
  return null;
}

/** Deflections used this round (per combat round; unlimited outside combat). */
function usedThisRound(defender) {
  const used = defender.getFlag(MODULE_ID, "deflected");
  const combat = game.combat;
  return combat?.started && used?.combat === combat.id && used.round === combat.round ? used.count : 0;
}

/* -------------------------------------------- */
/*  The card                                    */
/* -------------------------------------------- */

Hooks.on("pf1PreDisplayActionUse", (use) => {
  const action = use.action;
  if (!RANGED_ATTACKS.includes(action?.actionType)) return;
  const targets = (use.shared.targets ?? []).map((t) => t.document ?? t).filter((t) => t?.actor);
  const pinpoint = !!rollPlan(use.shared.rollData)?.provided?.some((p) => p.pinpoint);
  const gun = loading(use.actor, use.item);
  const mine = use.token?.object ?? use.actor?.getActiveTokens()[0];
  const increment = ((Number(action.range?.value) || 0) + rangeChanges(use.actor, action).add) || 0;
  const out = [];
  for (const token of targets) {
    const defender = token.actor;
    const changes = acAgainstRanged(defender, action);
    const deflector = deflectorOf(defender, action);
    const dist = tokenDistance(mine, token.object);
    const firearmTouch = !!gun?.firearm && increment > 0 && dist != null && dist <= increment * (gun.advanced ? 5 : 1);
    if (!changes.length && !deflector && !firearmTouch && !pinpoint) continue;
    const ac = defender.system.attributes.ac;
    const touch = !!action.touch || firearmTouch;
    let base = ac?.[touch ? "touch" : "normal"]?.total ?? null;
    // Pinpoint Targeting: no armor, natural armor or shield bonus (touch AC already has none)
    if (pinpoint && !touch && base != null) base -= ["normal", "shield", "natural"].reduce((t, k) => t + Math.max(0, defender.system.ac?.[k]?.total ?? 0), 0);
    out.push({ uuid: token.uuid, name: token.name, ac: base, changes, deflector, firearmTouch, pinpoint });
  }
  if (!out.length) return;
  const totals = use.shared.chatAttacks.map((a) => ({ total: a.attack?.total ?? null, natural: a.attack?.d20?.total ?? a.attack?.dice?.[0]?.total ?? null }));
  use.shared.chatData[`flags.${MODULE_ID}.${FLAG}`] = { targets: out, totals, deflected: {} };
});

function line(html, ok) {
  const div = document.createElement("div");
  div.className = `${MODULE_ID}-ranged-defense`;
  div.style.cssText = `margin: 0.25em 0; padding: 0 4px; border-left: 3px solid ${ok ? "#5a5" : "#b33"};`;
  div.innerHTML = html;
  return div;
}

Hooks.on("renderChatMessagePF", (message, html) => {
  const data = message.getFlag(MODULE_ID, FLAG);
  if (!data) return;
  html.querySelectorAll(".chat-attack[data-index]").forEach((el) => {
    const i = Number(el.dataset.index);
    const roll = data.totals?.[i];
    if (!roll) return;
    const lines = [];
    data.targets.forEach((t, k) => {
      const done = data.deflected?.[`${k}-${i}`];
      if (done) return lines.push(line(`<strong>${esc(t.name)}</strong> ${done.caught ? "caught" : "deflected"} it (${esc(done.by)}): no damage`, false));
      const actor = fromUuidSync(t.uuid)?.actor;
      const seesStats = game.user.isGM || !!actor?.isOwner; // enemy statistics stay hidden from players
      const bonus = t.changes.reduce((s, c) => s + c.value, 0);
      if (seesStats && (bonus || t.firearmTouch || t.pinpoint) && t.ac != null && roll.total != null) {
        const ac = t.ac + bonus;
        const hits = roll.natural === 20 || (roll.natural !== 1 && roll.total >= ac);
        const why = [
          t.firearmTouch ? "touch AC: a firearm within range" : null,
          t.pinpoint ? "no armor, natural armor or shield: Pinpoint Targeting" : null,
          ...t.changes.map((c) => `${c.value > 0 ? "+" : ""}${c.value} ${esc(c.label)}`),
        ].filter(Boolean);
        lines.push(line(`<strong>${esc(t.name)}</strong>: AC ${ac} against this ranged attack (${why.join(", ")}): ${roll.total} ${hits ? "hits" : "misses"}`, !hits));
      }
      if (t.deflector && actor && (game.user.isGM || actor.isOwner) && usedThisRound(actor) < t.deflector.perRound) {
        const d = t.deflector;
        const div = line(`<strong>${esc(t.name)}</strong> can deflect it if it hits${d.save ? ` (Reflex DC ${d.save})` : d.cutFromTheAir ? ` (a melee attack roll above ${roll.total})` : ""}:`, true);
        const button = document.createElement("button");
        button.type = "button";
        button.textContent = d.label;
        button.style.cssText = "width: auto; line-height: 1.4; margin: 2px 0.25em; padding: 0 6px;";
        button.addEventListener("click", async (event) => {
          event.preventDefault();
          button.disabled = true;
          if (game.user.isGM) await deflect(message, k, i);
          else await ChatMessage.implementation.create({ whisper: game.users.filter((u) => u.isGM).map((u) => u.id), content: `<p>${esc(t.name)} deflects a ranged attack (${esc(d.label)})…</p>`, flags: { [MODULE_ID]: { deflectRanged: { message: message.id, target: k, index: i } } } });
        });
        div.append(button);
        lines.push(div);
      }
    });
    const table = el.querySelector("table");
    if (lines.length) table ? table.after(...lines) : el.append(...lines);
  });
});

/** The defender deflects attack `index` (GM): roll the shield's save if there is one, count the use. */
export async function deflect(message, k, index) {
  const data = message.getFlag(MODULE_ID, FLAG);
  const t = data?.targets?.[k];
  const actor = fromUuidSync(t?.uuid)?.actor;
  if (!actor || !t.deflector || data.deflected?.[`${k}-${index}`] || usedThisRound(actor) >= t.deflector.perRound) return null;
  const d = t.deflector;
  if (d.save) {
    const save = await actor.rollSavingThrow("ref", { skipDialog: true, dc: d.save, reference: message.uuid });
    const total = save?.rolls?.[0]?.total ?? save?.total;
    if (!(Number.isFinite(total) && total >= d.save)) {
      await countUse(actor);
      return "failed";
    }
  }
  await countUse(actor);
  const result = { by: d.label, caught: !!d.catches };
  await message.update({ [`flags.${MODULE_ID}.${FLAG}.deflected.${k}-${index}`]: result });
  return result;
}

async function countUse(actor) {
  const combat = game.combat;
  if (!combat?.started) return;
  await actor.setFlag(MODULE_ID, "deflected", { combat: combat.id, round: combat.round, count: usedThisRound(actor) + 1 });
}

onGmRequest("deflectRanged", async (request, { message, target, index }) => {
  const card = game.messages.get(message);
  const actor = fromUuidSync(card?.getFlag(MODULE_ID, FLAG)?.targets?.[target]?.uuid)?.actor;
  if (card && requestedByOwner(request, actor)) await deflect(card, target, index);
  await request.delete();
});

/* -------------------------------------------- */
/*  Damage reduction against ranged weapons     */
/* -------------------------------------------- */

/** The best DR this defender has against this ranged weapon: { amount, label, pool? } or null. */
export function rangedDR(defender, action) {
  if (!WEAPON_ATTACKS.includes(action?.actionType)) return null;
  const magic = enhancement(action) > 0;
  const found = [];
  const arrows = buff(defender, /^protection from arrows/i);
  if (arrows && !magic) found.push({ amount: 10, label: arrows.name, pool: arrows });
  if (!magic && equippedItem(defender, /arrowmaster'?s bracers/i)) found.push({ amount: 5, label: "Arrowmaster's Bracers" });
  if (feat(defender, /^ranged defense \(archer\)/i)) found.push({ amount: 5, label: "Ranged Defense" });
  return found.reduce((a, b) => (!a || b.amount > a.amount ? b : a), null);
}

const poolLeft = (b) => b.getFlag(MODULE_ID, "absorbLeft") ?? Math.min(100, 10 * Math.max(1, b.system.level ?? 1));

// Damage applied from the card's buttons (PF1 passes the action): subtract the DR, after halving
Hooks.on("pf1ApplyDamage", (actor, options) => {
  const dr = rangedDR(actor, options.action);
  if (!dr || !(options.value > 0) || options[`${MODULE_ID}RangedDR`]) return;
  options[`${MODULE_ID}RangedDR`] = true;
  const damage = Math.max(0, Math.floor(options.value * (options.ratio ?? 1)) - (options.reduction ?? 0));
  let absorbed = Math.min(dr.amount, damage);
  if (dr.pool) absorbed = Math.min(absorbed, poolLeft(dr.pool));
  if (absorbed <= 0) return;
  options.reduction = (options.reduction ?? 0) + absorbed;
  ChatMessage.implementation.create({
    speaker: ChatMessage.implementation.getSpeaker({ actor }),
    whisper: game.users.filter((u) => u.isGM || actor.testUserPermission(u, "OWNER")).map((u) => u.id),
    content: `<p>${esc(actor.name)}: ${esc(dr.label)} absorbs ${absorbed} of the ranged weapon damage.</p>`,
  });
  if (dr.pool) {
    const left = poolLeft(dr.pool) - absorbed;
    if (left <= 0) dr.pool.update({ "system.active": false, [`flags.${MODULE_ID}.absorbLeft`]: null });
    else dr.pool.setFlag(MODULE_ID, "absorbLeft", left);
  }
});

/* -------------------------------------------- */
/*  Shooting while prone                        */
/* -------------------------------------------- */

Hooks.on("pf1CreateActionUse", (use) => {
  const action = use.action;
  const actor = use.actor;
  if (!actor?.statuses?.has("prone") || !WEAPON_ATTACKS.includes(action?.actionType)) return;
  const names = [action.item?.name ?? "", ...(action.item?.system?.baseTypes ?? [])].join(" ").toLowerCase();
  if (/crossbow|shuriken|pistol|musket|rifle|firearm|blunderbuss/.test(names)) return;
  if (/sling/.test(names) && feat(actor, /^prone slinger/i)) return;
  ui.notifications.warn(`${actor.name} is prone: most ranged weapons can't be used while prone (crossbows, shuriken and firearms can).`);
});

export const _test = { acAgainstRanged, deflectorOf, rangedDR, deflect, FLAG };
